mapper.select:
select id, type_id, code, customer_id, material_id, material_name, material_code, plan_start_time, plan_end_time, actual_start_time, actual_end_time, quantity, unit_id, production_line_id, state, craft_id, min_package_quantity, min_package_unit_id, note from pms_produce_order
del_flag = 0
AND state = #{dto.state}
and code LIKE CONCAT(CONCAT('%',#{dto.code}),'%')
and material_name LIKE CONCAT(CONCAT('%',#{dto.materialName}),'%')
and material_code LIKE CONCAT(CONCAT('%',#{dto.materialCode}),'%')
and type_id = #{dto.typeId}
and production_line_id = #{dto.productionLineId}
and plan_start_time between #{dto.planStartTimeStart} and #{dto.planStartTimeEnd}
and plan_end_time between #{dto.planEndTimeStart} and #{dto.planEndTimeEnd}
and actual_start_time between #{dto.actualStartDateStart} and #{dto.actualStartDateEnd}
and actual_end_time between #{dto.actualEndDateStart} and #{dto.actualEndDateEnd}
and (plan_start_time between #{dto.startTime} and #{dto.endTime} or plan_end_time between #{dto.startTime} and #{dto.endTime} )
Order By create_time DESC

select id, type_id, code, material_id, material_name, material_code, plan_start_time, plan_end_time, actual_start_time, actual_end_time, quantity, unit_id, production_line_id, state from pms_produce_order
del_flag = 0 and state != 0
and state = #{dto.state}
and production_line_id = #{dto.productionLineId}
and plan_start_time between #{dto.actualStartTime} and #{dto.actualEndTime}
order by create_time desc

select po.id, po.type_id, po.code, po.material_id, po.material_name, po.material_code, po.plan_start_time, po.plan_end_time, po.actual_start_time, po.actual_end_time, po.quantity, po.unit_id, po.production_line_id, po.state, po.craft_id from pms_produce_order po JOIN pms_produce_order_craft oc ON oc.produce_order_id = po.id JOIN pms_work_order_craft_station cs ON cs.produce_order_craft_id = oc.id JOIN pms_work_order_batch ob on ob.produce_order_id = po.id
po.del_flag = 0 and oc.del_flag = 0 and cs.del_flag = 0
and po.state = #{dto.state}
and ob.start_time >= #{dto.createDtStart}
and ob.start_time <= #{dto.createDtEnd}
and cs.execute_station_id = #{dto.stationId}
GROUP BY po.id order by po.create_time desc

SELECT o.production_line_id as productionLineId, o.`code` as code, o.material_id as materialId, o.material_code as materialCode, o.material_name as materialName, o.quantity as planQuantity, o.actual_start_time as actualStartTime, o.actual_end_time as actualEndTime, o.state as state, o.note as note, sum(c.quantity) as completeQuantity FROM pms_produce_order o LEFT JOIN pms_complete_storage_info c ON o.id = c.produce_order_id where o.production_line_id in
#{id}
GROUP BY o.id

SELECT ba.CODE as batchNo, ba.start_time, ba.end_time, po.material_id, po.material_name, po.production_line_id as productLine, po.`code` AS produce_order_no, po.id AS produce_order_id FROM `pms_work_order_batch` ba JOIN pms_produce_order po ON ba.produce_order_id = po.id WHERE ba.del_flag = 0 AND po.del_flag = 0 AND po.type_id = #{typeId} AND ba.id NOT IN ( SELECT id FROM pms_work_order_batch t WHERE (t.start_time >= #{end} OR t.end_time <= #{start}))
AND po.production_line_id in
#{id}
